export const faqItemsByLang: Record<string, QA[]> = {
  zh: [
    { question: '你们的最低起订量（MOQ）是多少？', answer: '我们的标准起订量为每款每色 300 件。定制设计的起订量可能因材料和工艺复杂程度而异。具体要求请联系销售团队，我们可为长期合作伙伴灵活安排。' },
    { question: '你们提供 OEM 和 ODM 服务吗？', answer: '是的！可米专注于 OEM（按客户设计代工生产）和 ODM（原始设计制造）服务。OEM：严格按照您的规格和设计生产眼镜。ODM：内部设计团队根据您的目标市场和偏好，为您的品牌打造专属系列。两项服务均支持材料、颜色、标志及包装的全面定制。' },
    { question: '你们的生产周期是多久？', answer: '标准生产周期为样品确认后 25-35 天。能否安排加急订单取决于当时的产能。样品开发通常需要 7-10 天。大货运输时间因目的地和方式而异：空运 5-7 天，海运 25-35 天。' },
    { question: '大货生产前可以先订样品吗？', answer: '当然可以。我们提供样品开发服务，方便您在确认大货生产前评估质量、佩戴贴合度及表面处理。样品费通常可抵扣大货订单金额。我们可按您的规格制作样品，包括定制颜色、材料及品牌标识。' },
    { question: '你们使用哪些眼镜材料？', answer: '我们使用多种材料：优质醋酸纤维板材（Mazzucchelli、Eastman）、钛（纯钛和 β 钛）、不锈钢、蒙乃尔合金、TR90、Ultem、碳纤维、水牛角及木材。所有材料均采购自经认证的供应商，并符合国际安全标准（FDA、CE、RoHS、加州第 65 号提案）。' },
    { question: '你们的产品有哪些认证？', answer: '我们的眼镜符合 FDA（美国）、CE（欧盟）、RoHS 及加州第 65 号提案等国际标准。整个生产过程均执行严格的质量控制，可按要求提供认证文件，供您存档及合规使用。' },
    { question: '你们提供定制包装及品牌标识服务吗？', answer: '是的，我们提供完整的品牌定制方案：镜架标志镭雕或印刷、定制镜腿脚套、品牌眼镜盒、清洁布、包装盒及吊牌。所有包装材料均可与您的品牌配色及设计风格保持一致。' },
    { question: '你们接受哪些付款条件？', answer: '标准付款条件为支付 30% 定金后开始生产，出货前支付 70% 尾款。我们接受 T/T（电汇），大额订单也可使用信用证（L/C）。已有稳定合作关系的客户可协商付款条件。' },
    { question: '你们可以发货到哪些地区？', answer: '我们面向全球发货，主要市场包括美国、欧盟、英国、日本、韩国、澳大利亚、中东及东南亚。我们与可靠的货运伙伴合作，提供空运及海运服务。' },
    { question: '如何获取报价？', answer: '请访问报价页面（/zh/quote/），填写表单并说明需求，包括镜架类型、材料偏好、预计数量及具体设计要求。销售团队通常会在 24 小时内回复。' },
    { question: '你们可以按现有镜架设计制作吗？', answer: '可以，我们能够复刻或调整现有镜架设计。请提供参考图片、技术图纸或实物样品，工程团队将据此制定可用于生产的规格。我们确保所有设计均尊重知识产权。' },
    { question: '你们的质量控制流程是什么？', answer: '每副镜架均经过多阶段质量检验：来料检验、生产过程质检、最终检验（对外观、佩戴贴合度、表面处理及尺寸精度进行 100% 检查），以及出货前随机抽检。每个生产批次均保留详细质检报告。' },
  ],
  de: [
    { question: 'Wie hoch ist Ihre Mindestbestellmenge (MOQ)?', answer: 'Unsere Standard-Mindestbestellmenge beträgt 300 Stück pro Modell und Farbe. Bei Sonderanfertigungen kann sie je nach Material und Komplexität variieren. Kontaktieren Sie unser Vertriebsteam für Ihre konkreten Anforderungen – für langfristige Partner sind wir flexibel.' },
    { question: 'Bieten Sie OEM- und ODM-Dienstleistungen an?', answer: 'Ja! Kssmi ist auf OEM (Fertigung nach Kundenvorgaben) und ODM (Originaldesign und Fertigung) spezialisiert. OEM: Wir fertigen Brillen exakt nach Ihren Spezifikationen und Entwürfen. ODM: Unser internes Designteam entwickelt exklusive Kollektionen für Ihre Marke, abgestimmt auf Ihren Zielmarkt und Ihre Wünsche. Beide Leistungen umfassen die individuelle Gestaltung von Materialien, Farben, Logos und Verpackungen.' },
    { question: 'Wie lange dauert die Produktion?', answer: 'Die reguläre Produktionszeit beträgt 25-35 Tage nach Musterfreigabe. Eilaufträge sind je nach aktueller Auslastung möglich. Die Musterentwicklung dauert in der Regel 7-10 Tage. Die Transportzeit für Serienaufträge hängt von Zielort und Versandart ab: Luftfracht 5-7 Tage, Seefracht 25-35 Tage.' },
    { question: 'Kann ich vor der Serienproduktion Muster bestellen?', answer: 'Selbstverständlich. Wir entwickeln Muster, damit Sie Qualität, Passform und Oberflächenverarbeitung vor der Serienfreigabe prüfen können. Musterkosten werden in der Regel auf Ihren Serienauftrag angerechnet. Wir fertigen Muster nach Ihren Vorgaben, einschließlich individueller Farben, Materialien und Markenkennzeichnung.' },
    { question: 'Welche Materialien verwenden Sie für Ihre Brillen?', answer: 'Wir verarbeiten zahlreiche Materialien: hochwertiges Acetat (Mazzucchelli, Eastman), Titan (Rein- und Beta-Titan), Edelstahl, Monel, TR90, Ultem, Kohlefaser, Wasserbüffelhorn und Holz. Alle Materialien stammen von zertifizierten Lieferanten und entsprechen internationalen Sicherheitsstandards (FDA, CE, RoHS, California Prop 65).' },
    { question: 'Welche Zertifizierungen haben Ihre Produkte?', answer: 'Unsere Brillen entsprechen internationalen Standards wie FDA (USA), CE (EU), RoHS und California Proposition 65. Wir führen während der gesamten Produktion strenge Qualitätskontrollen durch. Zertifizierungsunterlagen stellen wir auf Anfrage für Ihre Konformitätsdokumentation bereit.' },
    { question: 'Bieten Sie individuelle Verpackungen und Markenkennzeichnung an?', answer: 'Ja, wir bieten umfassende Markenlösungen: individuelle Logogravur oder Logodruck auf Fassungen, maßgeschneiderte Bügelenden, Etuis mit Markenkennzeichnung, Reinigungstücher, Schachteln und Anhänger. Sämtliche Verpackungsmaterialien können wir auf Ihre Markenfarben und Designsprache abstimmen.' },
    { question: 'Welche Zahlungsbedingungen akzeptieren Sie?', answer: 'Unsere Standardbedingungen sind 30% Anzahlung zum Produktionsstart und 70% Restzahlung vor Versand. Wir akzeptieren T/T (Banküberweisung) sowie Akkreditive (L/C) für größere Aufträge. Bei bestehenden Partnerschaften können die Zahlungsbedingungen vereinbart werden.' },
    { question: 'In welche Länder liefern Sie?', answer: 'Wir liefern weltweit. Zu unseren wichtigsten Märkten zählen die USA, die Europäische Union, das Vereinigte Königreich, Japan, Südkorea, Australien, der Nahe Osten und Südostasien. Für Luft- und Seefracht arbeiten wir mit zuverlässigen Transportpartnern zusammen.' },
    { question: 'Wie fordere ich ein Angebot an?', answer: 'Besuchen Sie unsere Angebotsseite (/de/quote/) und füllen Sie das Formular mit Ihren Anforderungen aus. Geben Sie Fassungsart, bevorzugtes Material, geschätzte Menge und besondere Designwünsche an. Unser Vertriebsteam antwortet in der Regel innerhalb von 24 Stunden.' },
    { question: 'Können Sie ein vorhandenes Fassungsdesign nachbilden?', answer: 'Ja, wir können bestehende Fassungsdesigns nachbilden oder anpassen. Stellen Sie uns Referenzbilder, technische Zeichnungen oder physische Muster zur Verfügung. Unser Entwicklungsteam erstellt daraus produktionsreife Spezifikationen. Wir achten bei allen Designs auf die Rechte am geistigen Eigentum.' },
    { question: 'Wie läuft Ihre Qualitätskontrolle ab?', answer: 'Jede Fassung durchläuft mehrere Prüfstufen: Wareneingangskontrolle, Qualitätskontrolle während der Fertigung, Endkontrolle (100% Prüfung von Aussehen, Passform, Oberflächenverarbeitung und Maßgenauigkeit) sowie Stichproben vor dem Versand. Für jede Produktionscharge führen wir detaillierte Prüfberichte.' },
  ],
  es: [
    { question: '¿Cuál es su cantidad mínima de pedido (MOQ)?', answer: 'Nuestro MOQ estándar es de 300 unidades por modelo y color. Para diseños personalizados, puede variar según el material y la complejidad. Consulte los requisitos específicos con nuestro equipo comercial; ofrecemos flexibilidad a nuestros socios a largo plazo.' },
    { question: '¿Ofrecen servicios OEM y ODM?', answer: '¡Sí! Kssmi se especializa en OEM (fabricación según el diseño del cliente) y ODM (diseño y fabricación originales). OEM: fabricamos gafas siguiendo exactamente sus especificaciones y diseños. ODM: nuestro equipo interno crea colecciones exclusivas para su marca según su mercado objetivo y preferencias. Ambos servicios incluyen la personalización completa de materiales, colores, logotipos y embalajes.' },
    { question: '¿Cuál es su plazo de producción?', answer: 'El plazo estándar es de 25-35 días tras la aprobación de la muestra. Podemos atender pedidos urgentes según la capacidad de producción disponible. El desarrollo de muestras suele tardar 7-10 días. El transporte de pedidos a granel depende del destino y del método: aéreo, 5-7 días; marítimo, 25-35 días.' },
    { question: '¿Puedo pedir muestras antes de la producción en serie?', answer: 'Por supuesto. Desarrollamos muestras para que pueda evaluar la calidad, el ajuste y el acabado antes de confirmar la producción en serie. Normalmente, el coste de las muestras se descuenta del pedido a granel. Podemos fabricarlas según sus especificaciones, incluidos colores, materiales e identidad de marca personalizados.' },
    { question: '¿Qué materiales utilizan para sus gafas?', answer: 'Trabajamos con diversos materiales: acetato de alta calidad (Mazzucchelli, Eastman), titanio puro y beta, acero inoxidable, Monel, TR90, Ultem, fibra de carbono, cuerno de búfalo y madera. Todos proceden de proveedores certificados y cumplen las normas internacionales de seguridad (FDA, CE, RoHS, Proposición 65 de California).' },
    { question: '¿Qué certificaciones tienen sus productos?', answer: 'Nuestras gafas cumplen normas internacionales como FDA (EE. UU.), CE (UE), RoHS y la Proposición 65 de California. Mantenemos un estricto control de calidad durante toda la producción. La documentación de certificación está disponible bajo petición para sus registros de cumplimiento.' },
    { question: '¿Ofrecen embalajes e identidad de marca personalizados?', answer: 'Sí, ofrecemos soluciones integrales de marca: grabado o impresión de logotipos en las monturas, terminales de varilla personalizados, estuches con su marca, paños de limpieza, cajas y etiquetas colgantes. Podemos adaptar todos los materiales de embalaje a los colores y al lenguaje visual de su marca.' },
    { question: '¿Qué condiciones de pago aceptan?', answer: 'Nuestras condiciones estándar son un anticipo del 30% para iniciar la producción y el 70% restante antes del envío. Aceptamos T/T (transferencia bancaria) y cartas de crédito (L/C) para pedidos de mayor volumen. Las condiciones pueden negociarse en relaciones comerciales consolidadas.' },
    { question: '¿A dónde realizan envíos?', answer: 'Enviamos a todo el mundo. Nuestros principales mercados incluyen Estados Unidos, la Unión Europea, el Reino Unido, Japón, Corea del Sur, Australia, Oriente Medio y el Sudeste Asiático. Trabajamos con socios logísticos fiables para el transporte aéreo y marítimo.' },
    { question: '¿Cómo puedo solicitar un presupuesto?', answer: 'Visite nuestra página de presupuestos (/es/quote/) y rellene el formulario con sus requisitos. Incluya el tipo de montura, el material preferido, la cantidad estimada y cualquier petición de diseño específica. Nuestro equipo comercial suele responder en un plazo de 24 horas.' },
    { question: '¿Pueden reproducir un diseño de montura existente?', answer: 'Sí, podemos reproducir o adaptar diseños de monturas existentes. Envíenos imágenes de referencia, planos técnicos o muestras físicas, y nuestro equipo de ingeniería elaborará las especificaciones para producción. Garantizamos que todos los diseños respeten los derechos de propiedad intelectual.' },
    { question: '¿Cuál es su proceso de control de calidad?', answer: 'Cada montura pasa por varias fases de inspección: control de materiales recibidos, control durante la producción, inspección final (revisión del 100% de la apariencia, el ajuste, el acabado y la precisión dimensional) y muestreo aleatorio previo al envío. Conservamos informes detallados de cada lote.' },
  ],
  fr: [
    { question: 'Quelle est votre quantité minimale de commande (MOQ) ?', answer: 'Notre MOQ standard est de 300 pièces par modèle et par couleur. Pour les créations sur mesure, elle peut varier selon le matériau et la complexité. Contactez notre équipe commerciale pour vos besoins précis ; nous faisons preuve de souplesse envers nos partenaires de longue date.' },
    { question: 'Proposez-vous des services OEM et ODM ?', answer: 'Oui ! Kssmi est spécialisée dans les services OEM (fabrication selon les plans du client) et ODM (conception et fabrication originales). OEM : nous fabriquons des lunettes selon vos spécifications et vos dessins exacts. ODM : notre équipe de conception interne crée des collections exclusives pour votre marque, selon votre marché cible et vos préférences. Les deux services incluent la personnalisation des matériaux, couleurs, logos et emballages.' },
    { question: 'Quel est votre délai de production ?', answer: 'Le délai standard est de 25-35 jours après validation de l’échantillon. Les commandes urgentes peuvent être acceptées selon les capacités de production disponibles. Le développement des échantillons prend généralement 7-10 jours. Le transport des commandes en série varie selon la destination et le mode : aérien, 5-7 jours ; maritime, 25-35 jours.' },
    { question: 'Puis-je commander des échantillons avant la production en série ?', answer: 'Absolument. Nous développons des échantillons pour vous permettre d’évaluer la qualité, l’ajustement et la finition avant de confirmer la production en série. Les frais d’échantillonnage sont généralement déduits de votre commande en série. Nous pouvons réaliser des échantillons selon vos spécifications, y compris les couleurs, matériaux et marquages personnalisés.' },
    { question: 'Quels matériaux utilisez-vous pour vos lunettes ?', answer: 'Nous travaillons de nombreux matériaux : acétate de qualité supérieure (Mazzucchelli, Eastman), titane pur et bêta, acier inoxydable, Monel, TR90, Ultem, fibre de carbone, corne de buffle et bois. Tous proviennent de fournisseurs certifiés et respectent les normes internationales de sécurité (FDA, CE, RoHS, Proposition 65 de Californie).' },
    { question: 'Quelles certifications possèdent vos produits ?', answer: 'Nos lunettes respectent les normes internationales, notamment FDA (États-Unis), CE (UE), RoHS et la Proposition 65 de Californie. Nous appliquons un contrôle qualité rigoureux tout au long de la production. Les documents de certification sont disponibles sur demande pour vos dossiers de conformité.' },
    { question: 'Proposez-vous des emballages et un marquage personnalisés ?', answer: 'Oui, nous proposons des solutions de marque complètes : gravure ou impression de logos sur les montures, embouts de branches personnalisés, étuis à votre marque, chiffons de nettoyage, boîtes et étiquettes suspendues. Tous les emballages peuvent reprendre la palette de couleurs et le langage visuel de votre marque.' },
    { question: 'Quelles conditions de paiement acceptez-vous ?', answer: 'Nos conditions standard sont un acompte de 30% au lancement de la production et le solde de 70% avant expédition. Nous acceptons les virements bancaires T/T et les lettres de crédit (L/C) pour les commandes importantes. Les conditions peuvent être négociées pour les partenariats établis.' },
    { question: 'Vers quelles destinations expédiez-vous ?', answer: 'Nous expédions dans le monde entier. Nos principaux marchés sont les États-Unis, l’Union européenne, le Royaume-Uni, le Japon, la Corée du Sud, l’Australie, le Moyen-Orient et l’Asie du Sud-Est. Nous collaborons avec des partenaires fiables pour le fret aérien et maritime.' },
    { question: 'Comment demander un devis ?', answer: 'Consultez notre page de devis (/fr/quote/) et remplissez le formulaire en précisant vos besoins : type de monture, matériau souhaité, quantité estimée et demandes de conception particulières. Notre équipe commerciale répond généralement sous 24 heures.' },
    { question: 'Pouvez-vous reproduire un modèle de monture existant ?', answer: 'Oui, nous pouvons reproduire ou adapter des modèles existants. Fournissez des images de référence, des plans techniques ou des échantillons physiques, et notre équipe d’ingénierie établira les spécifications de fabrication. Nous veillons au respect des droits de propriété intellectuelle pour tous les modèles.' },
    { question: 'Quel est votre processus de contrôle qualité ?', answer: 'Chaque monture subit plusieurs contrôles : inspection des matières entrantes, contrôle en cours de production, inspection finale (contrôle à 100% de l’aspect, de l’ajustement, de la finition et de la précision dimensionnelle) et échantillonnage aléatoire avant expédition. Nous conservons des rapports détaillés pour chaque lot de production.' },
  ],
  it: [
    { question: 'Qual è la vostra quantità minima d’ordine (MOQ)?', answer: 'Il nostro MOQ standard è di 300 pezzi per modello e colore. Per i progetti personalizzati può variare in base al materiale e alla complessità. Contattate il nostro team commerciale per le vostre esigenze specifiche: siamo flessibili con i partner di lunga durata.' },
    { question: 'Offrite servizi OEM e ODM?', answer: 'Sì! Kssmi è specializzata in OEM (produzione su progetto del cliente) e ODM (progettazione e produzione originali). OEM: realizziamo occhiali secondo le vostre specifiche e i vostri disegni esatti. ODM: il nostro team di design interno crea collezioni esclusive per il vostro marchio in base al mercato di riferimento e alle vostre preferenze. Entrambi i servizi includono la personalizzazione completa di materiali, colori, loghi e confezioni.' },
    { question: 'Quali sono i vostri tempi di produzione?', answer: 'Il tempo standard è di 25-35 giorni dalla conferma del campione. Gli ordini urgenti possono essere accettati in base alla capacità produttiva disponibile. Lo sviluppo dei campioni richiede in genere 7-10 giorni. Il trasporto degli ordini in serie varia secondo destinazione e modalità: aereo, 5-7 giorni; marittimo, 25-35 giorni.' },
    { question: 'Posso ordinare campioni prima della produzione in serie?', answer: 'Certamente. Sviluppiamo campioni per consentirvi di valutare qualità, vestibilità e finitura prima di confermare la produzione in serie. I costi dei campioni vengono generalmente detratti dall’ordine in serie. Possiamo realizzare campioni secondo le vostre specifiche, compresi colori, materiali e marchi personalizzati.' },
    { question: 'Quali materiali utilizzate per i vostri occhiali?', answer: 'Lavoriamo numerosi materiali: acetato di alta qualità (Mazzucchelli, Eastman), titanio puro e beta, acciaio inossidabile, Monel, TR90, Ultem, fibra di carbonio, corno di bufalo e legno. Tutti provengono da fornitori certificati e rispettano gli standard internazionali di sicurezza (FDA, CE, RoHS, Proposition 65 della California).' },
    { question: 'Quali certificazioni hanno i vostri prodotti?', answer: 'I nostri occhiali rispettano gli standard internazionali, tra cui FDA (USA), CE (UE), RoHS e Proposition 65 della California. Applichiamo rigorosi controlli di qualità durante tutta la produzione. La documentazione di certificazione è disponibile su richiesta per i vostri archivi di conformità.' },
    { question: 'Offrite confezioni e personalizzazioni del marchio?', answer: 'Sì, offriamo soluzioni complete: incisione o stampa del logo sulle montature, terminali delle aste personalizzati, astucci con il marchio, panni per la pulizia, scatole e cartellini. Possiamo coordinare tutti i materiali di confezionamento con i colori e il linguaggio visivo del vostro marchio.' },
    { question: 'Quali condizioni di pagamento accettate?', answer: 'Le condizioni standard prevedono un acconto del 30% per avviare la produzione e il saldo del 70% prima della spedizione. Accettiamo T/T (bonifico bancario) e lettere di credito (L/C) per gli ordini più consistenti. Le condizioni sono negoziabili per le collaborazioni consolidate.' },
    { question: 'Dove spedite?', answer: 'Spediamo in tutto il mondo. I mercati principali includono Stati Uniti, Unione europea, Regno Unito, Giappone, Corea del Sud, Australia, Medio Oriente e Sud-est asiatico. Collaboriamo con partner logistici affidabili per il trasporto aereo e marittimo.' },
    { question: 'Come posso richiedere un preventivo?', answer: 'Visitate la pagina dei preventivi (/it/quote/) e compilate il modulo con le vostre esigenze. Indicate tipo di montatura, materiale preferito, quantità stimata ed eventuali richieste specifiche di design. Il nostro team commerciale risponde generalmente entro 24 ore.' },
    { question: 'Potete riprodurre un modello di montatura esistente?', answer: 'Sì, possiamo riprodurre o adattare modelli esistenti. Fornite immagini di riferimento, disegni tecnici o campioni fisici e il nostro team di ingegneria preparerà le specifiche per la produzione. Garantiamo il rispetto dei diritti di proprietà intellettuale per tutti i progetti.' },
    { question: 'Qual è il vostro processo di controllo qualità?', answer: 'Ogni montatura supera più fasi di controllo: ispezione dei materiali in ingresso, controllo durante la produzione, ispezione finale (verifica al 100% di aspetto, vestibilità, finitura e precisione dimensionale) e campionamento casuale prima della spedizione. Conserviamo rapporti dettagliati per ogni lotto di produzione.' },
  ],
  pt: [
    { question: 'Qual é a quantidade mínima de pedido (MOQ)?', answer: 'Nosso MOQ padrão é de 300 peças por modelo e cor. Para projetos personalizados, pode variar conforme o material e a complexidade. Consulte nossa equipe comercial sobre suas necessidades específicas; oferecemos flexibilidade para parceiros de longo prazo.' },
    { question: 'Vocês oferecem serviços OEM e ODM?', answer: 'Sim! A Kssmi é especializada em OEM (fabricação conforme o projeto do cliente) e ODM (projeto e fabricação originais). OEM: produzimos óculos seguindo exatamente suas especificações e seus desenhos. ODM: nossa equipe interna cria coleções exclusivas para sua marca, conforme o mercado-alvo e suas preferências. Ambos os serviços incluem personalização completa de materiais, cores, logotipos e embalagens.' },
    { question: 'Qual é o prazo de produção?', answer: 'O prazo padrão é de 25-35 dias após a confirmação da amostra. Pedidos urgentes podem ser atendidos conforme a capacidade de produção disponível. O desenvolvimento de amostras normalmente leva 7-10 dias. O transporte dos pedidos em escala varia conforme o destino e a modalidade: aéreo, 5-7 dias; marítimo, 25-35 dias.' },
    { question: 'Posso pedir amostras antes da produção em escala?', answer: 'Com certeza. Desenvolvemos amostras para que você avalie qualidade, ajuste e acabamento antes de confirmar a produção em escala. O custo das amostras normalmente é abatido do pedido em escala. Podemos produzi-las conforme suas especificações, incluindo cores, materiais e identificação da marca personalizados.' },
    { question: 'Quais materiais vocês utilizam nos óculos?', answer: 'Trabalhamos com diversos materiais: acetato de alta qualidade (Mazzucchelli, Eastman), titânio puro e beta, aço inoxidável, Monel, TR90, Ultem, fibra de carbono, chifre de búfalo e madeira. Todos vêm de fornecedores certificados e atendem às normas internacionais de segurança (FDA, CE, RoHS, Proposição 65 da Califórnia).' },
    { question: 'Quais certificações seus produtos possuem?', answer: 'Nossos óculos atendem às normas internacionais, incluindo FDA (EUA), CE (UE), RoHS e Proposição 65 da Califórnia. Mantemos um rigoroso controle de qualidade durante toda a produção. A documentação de certificação está disponível mediante solicitação para seus registros de conformidade.' },
    { question: 'Vocês oferecem embalagens e identificação de marca personalizadas?', answer: 'Sim, oferecemos soluções completas de marca: gravação ou impressão de logotipos nas armações, ponteiras de hastes personalizadas, estojos com a marca, panos de limpeza, caixas e etiquetas pendentes. Podemos adequar todos os materiais de embalagem às cores e à linguagem visual da sua marca.' },
    { question: 'Quais condições de pagamento vocês aceitam?', answer: 'As condições padrão são 30% de entrada para iniciar a produção e 70% de saldo antes do envio. Aceitamos T/T (transferência bancária) e carta de crédito (L/C) para pedidos maiores. As condições podem ser negociadas para parcerias consolidadas.' },
    { question: 'Para onde vocês enviam?', answer: 'Enviamos para o mundo inteiro. Os principais mercados incluem Estados Unidos, União Europeia, Reino Unido, Japão, Coreia do Sul, Austrália, Oriente Médio e Sudeste Asiático. Trabalhamos com parceiros logísticos confiáveis para transporte aéreo e marítimo.' },
    { question: 'Como solicito um orçamento?', answer: 'Acesse nossa página de orçamentos (/pt/quote/) e preencha o formulário com seus requisitos. Inclua tipo de armação, material preferido, quantidade estimada e solicitações específicas de design. Nossa equipe comercial normalmente responde em até 24 horas.' },
    { question: 'Vocês podem reproduzir um modelo de armação existente?', answer: 'Sim, podemos reproduzir ou adaptar modelos existentes. Envie imagens de referência, desenhos técnicos ou amostras físicas, e nossa equipe de engenharia elaborará as especificações de produção. Garantimos que todos os projetos respeitem os direitos de propriedade intelectual.' },
    { question: 'Como funciona o controle de qualidade?', answer: 'Cada armação passa por várias inspeções: recebimento de materiais, controle durante a produção, inspeção final (verificação de 100% da aparência, do ajuste, do acabamento e da precisão dimensional) e amostragem aleatória antes do envio. Mantemos relatórios detalhados de cada lote de produção.' },
  ],
  ru: [
    { question: 'Каков минимальный объём заказа (MOQ)?', answer: 'Наш стандартный MOQ — 300 штук на модель в каждом цвете. Для индивидуальных разработок он может меняться в зависимости от материала и сложности. Обсудите конкретные требования с отделом продаж: для долгосрочных партнёров мы предлагаем гибкие условия.' },
    { question: 'Предоставляете ли вы услуги OEM и ODM?', answer: 'Да! Kssmi специализируется на OEM (производство по проекту заказчика) и ODM (разработка и производство оригинальных моделей). OEM: мы выпускаем очки точно по вашим спецификациям и дизайну. ODM: наша собственная команда дизайнеров создаёт эксклюзивные коллекции для вашего бренда с учётом целевого рынка и пожеланий. Обе услуги включают индивидуальный подбор материалов, цветов, логотипов и упаковки.' },
    { question: 'Каковы сроки производства?', answer: 'Стандартный срок производства — 25-35 дней после утверждения образца. Срочные заказы возможны в зависимости от текущей загрузки производства. Разработка образцов обычно занимает 7-10 дней. Доставка серийных заказов зависит от направления и способа: авиаперевозка — 5-7 дней, морская — 25-35 дней.' },
    { question: 'Можно ли заказать образцы до серийного производства?', answer: 'Конечно. Мы разрабатываем образцы, чтобы вы могли оценить качество, посадку и отделку до подтверждения серийного производства. Стоимость образцов обычно засчитывается в оплату серийного заказа. Мы изготовим их по вашим требованиям, включая индивидуальные цвета, материалы и фирменную маркировку.' },
    { question: 'Какие материалы вы используете для очков?', answer: 'Мы работаем с широким спектром материалов: высококачественный ацетат (Mazzucchelli, Eastman), титан (чистый и бета-титан), нержавеющая сталь, монель, TR90, Ultem, углеволокно, рог буйвола и дерево. Все материалы поставляются сертифицированными поставщиками и соответствуют международным требованиям безопасности (FDA, CE, RoHS, California Prop 65).' },
    { question: 'Какие сертификаты есть у вашей продукции?', answer: 'Наши очки соответствуют международным требованиям, включая FDA (США), CE (ЕС), RoHS и California Proposition 65. Мы строго контролируем качество на всех этапах производства. По запросу предоставляем сертификационные документы для подтверждения соответствия.' },
    { question: 'Предлагаете ли вы индивидуальную упаковку и брендирование?', answer: 'Да, мы предлагаем комплексное брендирование: гравировку или печать логотипа на оправах, индивидуальные наконечники заушников, фирменные футляры, салфетки, коробки и навесные бирки. Все упаковочные материалы можно выполнить в цветовой гамме и визуальном стиле вашего бренда.' },
    { question: 'Какие условия оплаты вы принимаете?', answer: 'Стандартные условия — предоплата 30% для запуска производства и остаток 70% перед отгрузкой. Принимаем T/T (банковский перевод), а для крупных заказов — аккредитив (L/C). Для постоянных партнёров условия оплаты обсуждаются индивидуально.' },
    { question: 'Куда вы доставляете заказы?', answer: 'Мы доставляем заказы по всему миру. Основные рынки: США, Европейский союз, Великобритания, Япония, Южная Корея, Австралия, Ближний Восток и Юго-Восточная Азия. Мы сотрудничаем с надёжными партнёрами по авиа- и морским перевозкам.' },
    { question: 'Как запросить коммерческое предложение?', answer: 'Откройте страницу запроса цены (/ru/quote/) и заполните форму с вашими требованиями. Укажите тип оправы, предпочтительный материал, примерное количество и особые пожелания к дизайну. Наш отдел продаж обычно отвечает в течение 24 часов.' },
    { question: 'Можете ли вы воспроизвести существующий дизайн оправы?', answer: 'Да, мы можем воспроизвести или адаптировать существующий дизайн. Предоставьте изображения, технические чертежи или физические образцы, и наши инженеры подготовят производственные спецификации. Мы обеспечиваем соблюдение прав интеллектуальной собственности во всех проектах.' },
    { question: 'Как устроен ваш контроль качества?', answer: 'Каждая оправа проходит несколько этапов проверки: входной контроль материалов, контроль в процессе производства, итоговую проверку (100% контроль внешнего вида, посадки, отделки и точности размеров) и выборочную проверку перед отгрузкой. Для каждой партии ведутся подробные отчёты о качестве.' },
  ],
  tr: [
    { question: 'Minimum sipariş miktarınız (MOQ) nedir?', answer: 'Standart MOQ değerimiz model ve renk başına 300 adettir. Özel tasarımlarda malzeme ve karmaşıklığa göre değişebilir. Özel gereksinimleriniz için satış ekibimizle iletişime geçin; uzun vadeli iş ortaklarımıza esneklik sağlıyoruz.' },
    { question: 'OEM ve ODM hizmetleri sunuyor musunuz?', answer: 'Evet! Kssmi, OEM (müşteri tasarımına göre üretim) ve ODM (özgün tasarım ve üretim) alanlarında uzmanlaşmıştır. OEM: gözlükleri tam olarak sizin teknik özellik ve tasarımlarınıza göre üretiriz. ODM: kendi tasarım ekibimiz, hedef pazarınıza ve tercihlerinize göre markanıza özel koleksiyonlar oluşturur. Her iki hizmette malzeme, renk, logo ve ambalaj tamamen özelleştirilebilir.' },
    { question: 'Üretim süreniz ne kadardır?', answer: 'Standart üretim süresi numune onayından sonra 25-35 gündür. Acil siparişler mevcut üretim kapasitesine göre kabul edilebilir. Numune geliştirme genellikle 7-10 gün sürer. Toplu siparişlerin taşıma süresi varış yerine ve yönteme göre değişir: hava yolu 5-7 gün, deniz yolu 25-35 gün.' },
    { question: 'Seri üretimden önce numune sipariş edebilir miyim?', answer: 'Elbette. Seri üretimi onaylamadan önce kaliteyi, uyumu ve yüzey işçiliğini değerlendirebilmeniz için numune geliştirme hizmeti sunuyoruz. Numune ücretleri genellikle toplu sipariş tutarından düşülür. Özel renkler, malzemeler ve marka uygulamaları dahil, şartlarınıza uygun numuneler üretebiliriz.' },
    { question: 'Gözlüklerinizde hangi malzemeleri kullanıyorsunuz?', answer: 'Yüksek kaliteli asetat (Mazzucchelli, Eastman), titanyum (saf ve beta), paslanmaz çelik, Monel, TR90, Ultem, karbon fiber, manda boynuzu ve ahşap gibi çeşitli malzemeler kullanıyoruz. Tüm malzemeler sertifikalı tedarikçilerden alınır ve uluslararası güvenlik standartlarına (FDA, CE, RoHS, California Prop 65) uygundur.' },
    { question: 'Ürünlerinizin hangi sertifikaları var?', answer: 'Gözlüklerimiz FDA (ABD), CE (AB), RoHS ve California Proposition 65 dahil uluslararası standartlara uygundur. Üretim boyunca sıkı kalite kontrol uygularız. Uygunluk kayıtlarınız için sertifika belgeleri talep üzerine sunulur.' },
    { question: 'Özel ambalaj ve markalama hizmeti sunuyor musunuz?', answer: 'Evet, kapsamlı marka çözümleri sunuyoruz: çerçevelere özel logo kazıma veya baskı, özel sap uçları, markalı gözlük kılıfları, temizleme bezleri, kutular ve askılı etiketler. Tüm ambalaj malzemelerini markanızın renk paletine ve tasarım diline uyarlayabiliriz.' },
    { question: 'Hangi ödeme koşullarını kabul ediyorsunuz?', answer: 'Standart koşullarımız üretime başlamak için %30 peşinat ve sevkiyattan önce %70 bakiye ödemesidir. T/T (banka havalesi) ve büyük siparişlerde akreditif (L/C) kabul ediyoruz. Yerleşik iş ortaklıklarında ödeme koşulları görüşülebilir.' },
    { question: 'Nerelere gönderim yapıyorsunuz?', answer: 'Dünya çapında gönderim yapıyoruz. Başlıca pazarlarımız ABD, Avrupa Birliği, Birleşik Krallık, Japonya, Güney Kore, Avustralya, Orta Doğu ve Güneydoğu Asya’dır. Hava ve deniz taşımacılığında güvenilir lojistik ortaklarıyla çalışıyoruz.' },
    { question: 'Nasıl fiyat teklifi isteyebilirim?', answer: 'Teklif sayfamızı (/tr/quote/) ziyaret ederek formu gereksinimlerinizle doldurun. Çerçeve türünü, malzeme tercihini, tahmini miktarı ve özel tasarım taleplerini belirtin. Satış ekibimiz genellikle 24 saat içinde yanıt verir.' },
    { question: 'Mevcut bir çerçeve tasarımını üretebilir misiniz?', answer: 'Evet, mevcut çerçeve tasarımlarını yeniden üretebilir veya uyarlayabiliriz. Referans görseller, teknik çizimler ya da fiziksel numuneler sağlamanız yeterlidir; mühendislik ekibimiz üretime hazır teknik özellikleri oluşturur. Tüm tasarımlarda fikrî mülkiyet haklarına saygı gösteririz.' },
    { question: 'Kalite kontrol süreciniz nasıldır?', answer: 'Her çerçeve çok aşamalı kontrolden geçer: gelen malzeme kontrolü, üretim sırasında kalite kontrol, son kontrol (görünüm, uyum, yüzey işçiliği ve boyut doğruluğunun %100 kontrolü) ve sevkiyat öncesi rastgele numune kontrolü. Her üretim partisi için ayrıntılı kalite raporları tutarız.' },
  ],
  ja: [
    { question: '最小発注数量（MOQ）はいくつですか？', answer: '標準のMOQは、モデル・色ごとに300本です。特注デザインの場合、素材や設計の複雑さにより異なる場合があります。具体的な条件は営業チームへご相談ください。長期的なお取引先には柔軟に対応します。' },
    { question: 'OEM・ODMサービスは提供していますか？', answer: 'はい。KssmiはOEM（お客様の設計に基づく受託製造）とODM（独自設計による製造）の両方を専門としています。OEMでは、お客様の仕様とデザインに忠実に眼鏡を製造します。ODMでは、社内のデザインチームが対象市場やご要望に合わせ、ブランド専用のコレクションを開発します。いずれも素材、色、ロゴ、パッケージを全面的にカスタマイズできます。' },
    { question: '生産期間はどのくらいですか？', answer: '標準の生産期間はサンプル承認後25-35日です。お急ぎの注文は、生産能力の空き状況に応じて対応可能です。サンプル開発には通常7-10日かかります。量産品の輸送日数は仕向地と輸送方法によって異なり、航空便は5-7日、船便は25-35日です。' },
    { question: '量産前にサンプルを注文できますか？', answer: 'もちろんです。量産をご決定いただく前に品質、フィット感、仕上げをご確認いただけるよう、サンプル開発サービスを提供しています。サンプル費用は通常、量産注文の代金に充当されます。特注色、素材、ブランド表示を含め、ご指定の仕様でサンプルを製作できます。' },
    { question: '眼鏡にはどのような素材を使用していますか？', answer: '高品質アセテート（Mazzucchelli、Eastman）、チタン（純チタン・βチタン）、ステンレス、モネル、TR90、Ultem、カーボンファイバー、水牛の角、木材など、幅広い素材を扱っています。すべて認証済みの供給業者から調達し、国際的な安全基準（FDA、CE、RoHS、カリフォルニア州プロポジション65）に適合しています。' },
    { question: '製品はどのような認証に対応していますか？', answer: '当社の眼鏡は、FDA（米国）、CE（EU）、RoHS、カリフォルニア州プロポジション65などの国際基準に適合しています。生産の全工程で厳格な品質管理を行っています。適合性の記録に必要な認証書類は、ご要望に応じて提供します。' },
    { question: 'パッケージやブランド表示をカスタマイズできますか？', answer: 'はい。フレームへのロゴ刻印・印刷、特注のモダン（先セル）、ブランド入りケース、クリーニングクロス、箱、下げ札など、包括的なブランド対応を行っています。すべての包装資材をブランドカラーやデザインの世界観に合わせられます。' },
    { question: '支払条件を教えてください。', answer: '標準条件は、生産開始時に30%の前金、および出荷前に70%の残金をお支払いいただく形です。T/T（銀行送金）に対応し、大口注文では信用状（L/C）も利用できます。継続的なお取引の場合は支払条件をご相談いただけます。' },
    { question: 'どの地域へ発送していますか？', answer: '世界各地へ発送しています。主な市場は米国、欧州連合、英国、日本、韓国、オーストラリア、中東、東南アジアです。航空便・船便ともに信頼できる物流パートナーと連携しています。' },
    { question: '見積もりはどのように依頼できますか？', answer: '見積もりページ（/ja/quote/）のフォームにご要望をご記入ください。フレームの種類、希望素材、予定数量、具体的なデザインのご要望などをお知らせください。営業チームが通常24時間以内に返信します。' },
    { question: '既存のフレームデザインに合わせて製作できますか？', answer: 'はい。既存のフレームデザインの再現や調整が可能です。参考画像、技術図面、または現物サンプルをご提供いただければ、エンジニアリングチームが生産用の仕様を作成します。すべてのデザインで知的財産権を尊重します。' },
    { question: '品質管理はどのように行っていますか？', answer: 'すべてのフレームに対し、入荷材料検査、工程内品質検査、最終検査（外観、フィット感、仕上げ、寸法精度を100%検査）、出荷前の無作為抜取検査という多段階の検査を行います。生産ロットごとに詳細な品質検査報告書を保管しています。' },
  ],
  ko: [
    { question: '최소 주문 수량(MOQ)은 얼마인가요?', answer: '표준 MOQ는 모델별, 색상별 300개입니다. 맞춤 디자인은 소재와 복잡도에 따라 달라질 수 있습니다. 구체적인 요구 사항은 영업팀에 문의해 주세요. 장기 협력사에는 유연하게 대응합니다.' },
    { question: 'OEM 및 ODM 서비스를 제공하나요?', answer: '네! Kssmi는 OEM(고객 설계에 따른 위탁 생산)과 ODM(자체 설계 및 생산)을 전문으로 합니다. OEM은 고객의 사양과 디자인에 정확히 맞춰 안경을 생산합니다. ODM은 자체 디자인팀이 목표 시장과 선호도에 따라 고객 브랜드만의 독점 컬렉션을 개발합니다. 두 서비스 모두 소재, 색상, 로고, 포장의 전체 맞춤 제작을 지원합니다.' },
    { question: '생산 기간은 얼마나 걸리나요?', answer: '표준 생산 기간은 샘플 승인 후 25-35일입니다. 긴급 주문은 당시 생산 여력에 따라 수용할 수 있습니다. 샘플 개발은 보통 7-10일이 걸립니다. 대량 주문의 운송 기간은 목적지와 방식에 따라 항공 5-7일, 해상 25-35일입니다.' },
    { question: '대량 생산 전에 샘플을 주문할 수 있나요?', answer: '물론입니다. 대량 생산을 결정하기 전에 품질, 착용감, 마감을 평가할 수 있도록 샘플 개발 서비스를 제공합니다. 샘플 비용은 일반적으로 대량 주문 금액에서 차감됩니다. 맞춤 색상, 소재, 브랜드 표시를 포함해 고객 사양에 맞는 샘플을 제작할 수 있습니다.' },
    { question: '안경에 어떤 소재를 사용하나요?', answer: '고급 아세테이트(Mazzucchelli, Eastman), 티타늄(순수 및 베타), 스테인리스강, 모넬, TR90, Ultem, 탄소섬유, 물소 뿔, 목재 등 다양한 소재를 사용합니다. 모든 소재는 인증된 공급업체에서 조달하며 국제 안전 기준(FDA, CE, RoHS, 캘리포니아 Proposition 65)을 준수합니다.' },
    { question: '제품은 어떤 인증 기준을 충족하나요?', answer: '당사 안경은 FDA(미국), CE(EU), RoHS, 캘리포니아 Proposition 65 등 국제 기준을 충족합니다. 전체 생산 과정에서 엄격한 품질 관리를 시행합니다. 규정 준수 기록에 필요한 인증 서류는 요청 시 제공합니다.' },
    { question: '맞춤 포장과 브랜드 표시 서비스를 제공하나요?', answer: '네, 안경테 로고 각인 및 인쇄, 맞춤 다리 팁, 브랜드 케이스, 클리닝 천, 상자, 행택 등 종합적인 브랜드 솔루션을 제공합니다. 모든 포장재에 브랜드 색상과 디자인 스타일을 일관되게 적용할 수 있습니다.' },
    { question: '결제 조건은 어떻게 되나요?', answer: '표준 조건은 생산 시작을 위한 계약금 30%, 출하 전 잔금 70%입니다. T/T(은행 송금)를 받으며 대규모 주문은 신용장(L/C)도 가능합니다. 기존 협력 관계에 대해서는 결제 조건을 협의할 수 있습니다.' },
    { question: '어느 지역으로 배송하나요?', answer: '전 세계로 배송합니다. 주요 시장은 미국, 유럽연합, 영국, 일본, 한국, 호주, 중동, 동남아시아입니다. 항공 및 해상 운송 모두 신뢰할 수 있는 물류 파트너와 협력합니다.' },
    { question: '견적은 어떻게 요청하나요?', answer: '견적 페이지(/ko/quote/)에서 요구 사항을 양식에 작성해 주세요. 안경테 종류, 선호 소재, 예상 수량, 구체적인 디자인 요청을 포함해 주세요. 영업팀이 보통 24시간 이내에 답변합니다.' },
    { question: '기존 안경테 디자인을 재현할 수 있나요?', answer: '네, 기존 안경테 디자인을 재현하거나 조정할 수 있습니다. 참고 이미지, 기술 도면 또는 실물 샘플을 제공하시면 엔지니어링팀이 생산용 사양을 작성합니다. 모든 디자인에서 지식재산권을 존중합니다.' },
    { question: '품질 관리 절차는 어떻게 되나요?', answer: '모든 안경테는 입고 소재 검사, 생산 공정 중 품질 검사, 최종 검사(외관, 착용감, 마감, 치수 정확도에 대한 100% 검사), 출하 전 무작위 표본 검사 등 여러 단계를 거칩니다. 생산 배치별로 상세한 품질 검사 보고서를 보관합니다.' },
  ],
  ar: [
    { question: 'ما الحد الأدنى لكمية الطلب (MOQ)؟', answer: 'الحد الأدنى القياسي لدينا هو 300 قطعة لكل موديل ولكل لون. وقد يختلف للتصاميم المخصصة حسب المادة ودرجة التعقيد. تواصل مع فريق المبيعات لمناقشة متطلباتك المحددة؛ فنحن نقدم مرونة لشركائنا على المدى الطويل.' },
    { question: 'هل تقدمون خدمات OEM وODM؟', answer: 'نعم! تتخصص Kssmi في خدمات OEM (التصنيع وفق تصميم العميل) وODM (التصميم والتصنيع الأصليين). في OEM ننتج النظارات وفق مواصفاتك وتصاميمك بدقة. وفي ODM يبتكر فريق التصميم الداخلي مجموعات حصرية لعلامتك التجارية وفق السوق المستهدفة وتفضيلاتك. تشمل الخدمتان التخصيص الكامل للمواد والألوان والشعارات والتغليف.' },
    { question: 'ما مدة الإنتاج لديكم؟', answer: 'مدة الإنتاج القياسية هي 25-35 يومًا بعد اعتماد العينة. يمكن قبول الطلبات العاجلة حسب الطاقة الإنتاجية المتاحة. يستغرق تطوير العينات عادةً 7-10 أيام. وتختلف مدة شحن الطلبات بالجملة حسب الوجهة والطريقة: جوًا 5-7 أيام، وبحرًا 25-35 يومًا.' },
    { question: 'هل يمكنني طلب عينات قبل الإنتاج بالجملة؟', answer: 'بالتأكيد. نقدم خدمات تطوير العينات لتقييم الجودة والملاءمة والتشطيب قبل اعتماد الإنتاج بالجملة. تُخصم رسوم العينات عادةً من قيمة طلبك بالجملة. ويمكننا إنتاج عينات تطابق مواصفاتك، بما فيها الألوان والمواد والعلامات التجارية المخصصة.' },
    { question: 'ما المواد التي تستخدمونها في النظارات؟', answer: 'نعمل بمواد متنوعة: الأسيتات عالي الجودة (Mazzucchelli وEastman)، والتيتانيوم النقي وبيتا، والفولاذ المقاوم للصدأ، والمونيل، وTR90، وUltem، وألياف الكربون، وقرن الجاموس، والخشب. تُورَّد جميع المواد من موردين معتمدين وتتوافق مع معايير السلامة الدولية (FDA وCE وRoHS ومقترح كاليفورنيا 65).' },
    { question: 'ما الشهادات التي تحملها منتجاتكم؟', answer: 'تتوافق نظاراتنا مع المعايير الدولية، ومنها FDA (الولايات المتحدة) وCE (الاتحاد الأوروبي) وRoHS ومقترح كاليفورنيا 65. نطبق رقابة صارمة على الجودة طوال الإنتاج. وتتوفر وثائق الشهادات عند الطلب لإضافتها إلى سجلات الامتثال لديك.' },
    { question: 'هل توفرون تغليفًا وعلامات تجارية مخصصة؟', answer: 'نعم، نقدم حلولًا متكاملة للعلامة التجارية: نقش أو طباعة الشعار على الإطارات، وأطراف أذرع مخصصة، وحافظات تحمل علامتك، وأقمشة تنظيف، وعلب، وبطاقات تعليق. يمكننا تنسيق ألوان جميع مواد التغليف وتصميمها مع الهوية البصرية لعلامتك.' },
    { question: 'ما شروط الدفع التي تقبلونها؟', answer: 'شروطنا القياسية هي دفعة مقدمة بنسبة 30% لبدء الإنتاج، والرصيد المتبقي بنسبة 70% قبل الشحن. نقبل T/T (التحويل البنكي) والاعتماد المستندي (L/C) للطلبات الكبيرة. ويمكن مناقشة شروط الدفع للشراكات القائمة.' },
    { question: 'إلى أين تشحنون؟', answer: 'نشحن إلى جميع أنحاء العالم. تشمل أسواقنا الرئيسية الولايات المتحدة والاتحاد الأوروبي والمملكة المتحدة واليابان وكوريا الجنوبية وأستراليا والشرق الأوسط وجنوب شرق آسيا. نتعاون مع شركاء شحن موثوقين للنقل الجوي والبحري.' },
    { question: 'كيف أطلب عرض سعر؟', answer: 'زر صفحة عرض السعر (/ar/quote/) واملأ النموذج بمتطلباتك. اذكر نوع الإطار والمادة المفضلة والكمية التقديرية وأي طلبات تصميم محددة. يرد فريق المبيعات عادةً خلال 24 ساعة.' },
    { question: 'هل يمكنكم مطابقة تصميم إطار موجود؟', answer: 'نعم، يمكننا إعادة إنتاج تصاميم الإطارات الموجودة أو تعديلها. قدّم صورًا مرجعية أو رسومات فنية أو عينات فعلية، وسيُعد فريق الهندسة المواصفات الجاهزة للإنتاج. ونضمن احترام حقوق الملكية الفكرية في جميع التصاميم.' },
    { question: 'ما إجراءات مراقبة الجودة لديكم؟', answer: 'يخضع كل إطار لفحص متعدد المراحل: فحص المواد الواردة، ومراقبة الجودة أثناء الإنتاج، والفحص النهائي (فحص بنسبة 100% للمظهر والملاءمة والتشطيب ودقة الأبعاد)، وأخذ عينات عشوائية قبل الشحن. ونحتفظ بتقارير جودة مفصلة لكل دفعة إنتاج.' },
  ],
  hi: [
    { question: 'आपकी न्यूनतम ऑर्डर मात्रा (MOQ) कितनी है?', answer: 'हमारा मानक MOQ प्रत्येक मॉडल के प्रत्येक रंग के लिए 300 पीस है। कस्टम डिज़ाइन के लिए यह सामग्री और जटिलता के अनुसार बदल सकता है। अपनी विशिष्ट आवश्यकताओं के लिए हमारी बिक्री टीम से संपर्क करें; दीर्घकालिक साझेदारों के लिए हम लचीली व्यवस्था रखते हैं।' },
    { question: 'क्या आप OEM और ODM सेवाएँ देते हैं?', answer: 'हाँ! Kssmi, OEM (ग्राहक के डिज़ाइन के अनुसार निर्माण) और ODM (मौलिक डिज़ाइन और निर्माण), दोनों में विशेषज्ञ है। OEM में हम आपके विनिर्देशों और डिज़ाइन के बिल्कुल अनुसार चश्मे बनाते हैं। ODM में हमारी अपनी डिज़ाइन टीम आपके लक्षित बाज़ार और पसंद के आधार पर आपके ब्रांड के लिए विशिष्ट कलेक्शन तैयार करती है। दोनों सेवाओं में सामग्री, रंग, लोगो और पैकेजिंग का पूरा अनुकूलन शामिल है।' },
    { question: 'आपका उत्पादन समय कितना है?', answer: 'नमूने की पुष्टि के बाद मानक उत्पादन समय 25-35 दिन है। तत्काल ऑर्डर वर्तमान उत्पादन क्षमता के अनुसार स्वीकार किए जा सकते हैं। नमूना विकसित करने में आमतौर पर 7-10 दिन लगते हैं। थोक ऑर्डर की ढुलाई का समय गंतव्य और माध्यम पर निर्भर करता है: हवाई मार्ग से 5-7 दिन, समुद्री मार्ग से 25-35 दिन।' },
    { question: 'क्या मैं बड़े पैमाने पर उत्पादन से पहले नमूने मँगा सकता हूँ?', answer: 'बिल्कुल। हम नमूना विकास सेवाएँ देते हैं ताकि आप बड़े पैमाने पर उत्पादन की पुष्टि से पहले गुणवत्ता, फिट और फिनिश का मूल्यांकन कर सकें। नमूनों का शुल्क आमतौर पर आपके थोक ऑर्डर की राशि में समायोजित किया जाता है। हम कस्टम रंग, सामग्री और ब्रांडिंग सहित आपके विनिर्देशों के अनुसार नमूने बना सकते हैं।' },
    { question: 'आप चश्मों में कौन-सी सामग्री इस्तेमाल करते हैं?', answer: 'हम कई प्रकार की सामग्री इस्तेमाल करते हैं: उच्च गुणवत्ता वाला एसीटेट (Mazzucchelli, Eastman), टाइटेनियम (शुद्ध और बीटा), स्टेनलेस स्टील, मोनेल, TR90, Ultem, कार्बन फाइबर, भैंस का सींग और लकड़ी। सभी सामग्री प्रमाणित आपूर्तिकर्ताओं से ली जाती है और अंतरराष्ट्रीय सुरक्षा मानकों (FDA, CE, RoHS, कैलिफ़ोर्निया प्रस्ताव 65) के अनुरूप होती है।' },
    { question: 'आपके उत्पादों के पास कौन-से प्रमाणन हैं?', answer: 'हमारे चश्मे FDA (अमेरिका), CE (यूरोपीय संघ), RoHS और कैलिफ़ोर्निया प्रस्ताव 65 सहित अंतरराष्ट्रीय मानकों को पूरा करते हैं। हम पूरे उत्पादन के दौरान कड़ी गुणवत्ता जाँच करते हैं। आपके अनुपालन रिकॉर्ड के लिए अनुरोध पर प्रमाणन दस्तावेज़ उपलब्ध हैं।' },
    { question: 'क्या आप कस्टम पैकेजिंग और ब्रांडिंग देते हैं?', answer: 'हाँ, हम संपूर्ण ब्रांडिंग समाधान देते हैं: फ्रेम पर कस्टम लोगो की नक्काशी या छपाई, कस्टम टेंपल टिप्स, ब्रांडेड केस, सफाई के कपड़े, बॉक्स और हैंग टैग। सभी पैकेजिंग सामग्री को आपके ब्रांड के रंगों और डिज़ाइन शैली से मिलाया जा सकता है।' },
    { question: 'आप भुगतान की कौन-सी शर्तें स्वीकार करते हैं?', answer: 'हमारी मानक शर्तें उत्पादन शुरू करने के लिए 30% अग्रिम और शिपमेंट से पहले 70% शेष भुगतान हैं। हम T/T (बैंक ट्रांसफ़र) और बड़े ऑर्डर के लिए साख पत्र (L/C) स्वीकार करते हैं। स्थापित साझेदारियों के लिए भुगतान की शर्तों पर चर्चा की जा सकती है।' },
    { question: 'आप कहाँ-कहाँ शिपिंग करते हैं?', answer: 'हम दुनिया भर में शिपिंग करते हैं। प्रमुख बाज़ारों में अमेरिका, यूरोपीय संघ, यूनाइटेड किंगडम, जापान, दक्षिण कोरिया, ऑस्ट्रेलिया, मध्य पूर्व और दक्षिण-पूर्व एशिया शामिल हैं। हम हवाई और समुद्री परिवहन के लिए भरोसेमंद माल ढुलाई साझेदारों के साथ काम करते हैं।' },
    { question: 'मैं मूल्य प्रस्ताव कैसे माँगूँ?', answer: 'हमारे मूल्य प्रस्ताव पेज (/hi/quote/) पर जाएँ और फ़ॉर्म में अपनी आवश्यकताएँ भरें। फ्रेम का प्रकार, पसंदीदा सामग्री, अनुमानित मात्रा और कोई विशेष डिज़ाइन अनुरोध शामिल करें। हमारी बिक्री टीम आमतौर पर 24 घंटे के भीतर जवाब देती है।' },
    { question: 'क्या आप मौजूदा फ्रेम डिज़ाइन के अनुरूप बना सकते हैं?', answer: 'हाँ, हम मौजूदा फ्रेम डिज़ाइन को दोबारा बना सकते हैं या उसमें बदलाव कर सकते हैं। संदर्भ चित्र, तकनीकी ड्रॉइंग या वास्तविक नमूने दें; हमारी इंजीनियरिंग टीम उत्पादन के लिए तैयार विनिर्देश बनाएगी। हम सुनिश्चित करते हैं कि सभी डिज़ाइन बौद्धिक संपदा अधिकारों का सम्मान करें।' },
    { question: 'आपकी गुणवत्ता नियंत्रण प्रक्रिया क्या है?', answer: 'हर फ्रेम की कई चरणों में जाँच होती है: आने वाली सामग्री की जाँच, उत्पादन के दौरान गुणवत्ता नियंत्रण, अंतिम जाँच (दिखावट, फिट, फिनिश और माप की सटीकता की 100% जाँच) और शिपमेंट से पहले यादृच्छिक नमूनों की जाँच। हम हर उत्पादन बैच की विस्तृत गुणवत्ता रिपोर्ट रखते हैं।' },
  ],
  vi: [
    { question: 'Số lượng đặt hàng tối thiểu (MOQ) là bao nhiêu?', answer: 'MOQ tiêu chuẩn của chúng tôi là 300 chiếc cho mỗi mẫu, mỗi màu. Với thiết kế riêng, MOQ có thể thay đổi tùy vật liệu và độ phức tạp. Hãy liên hệ đội ngũ kinh doanh về yêu cầu cụ thể; chúng tôi linh hoạt với các đối tác lâu dài.' },
    { question: 'Các bạn có cung cấp dịch vụ OEM và ODM không?', answer: 'Có! Kssmi chuyên về OEM (sản xuất theo thiết kế của khách hàng) và ODM (thiết kế và sản xuất nguyên bản). OEM: chúng tôi sản xuất kính đúng thông số và thiết kế của bạn. ODM: đội ngũ thiết kế nội bộ phát triển bộ sưu tập độc quyền cho thương hiệu của bạn dựa trên thị trường mục tiêu và sở thích. Cả hai dịch vụ đều cho phép tùy chỉnh toàn bộ vật liệu, màu sắc, logo và bao bì.' },
    { question: 'Thời gian sản xuất là bao lâu?', answer: 'Thời gian sản xuất tiêu chuẩn là 25-35 ngày sau khi duyệt mẫu. Đơn hàng gấp có thể được nhận tùy công suất sản xuất hiện tại. Phát triển mẫu thường mất 7-10 ngày. Thời gian vận chuyển đơn hàng số lượng lớn tùy điểm đến và phương thức: đường hàng không 5-7 ngày, đường biển 25-35 ngày.' },
    { question: 'Tôi có thể đặt mẫu trước khi sản xuất hàng loạt không?', answer: 'Chắc chắn có. Chúng tôi phát triển mẫu để bạn đánh giá chất lượng, độ vừa vặn và độ hoàn thiện trước khi quyết định sản xuất hàng loạt. Phí mẫu thường được khấu trừ vào đơn hàng số lượng lớn. Mẫu có thể được làm đúng thông số, bao gồm màu sắc, vật liệu và nhận diện thương hiệu riêng.' },
    { question: 'Các bạn sử dụng vật liệu nào để làm kính?', answer: 'Chúng tôi sử dụng nhiều vật liệu: acetate chất lượng cao (Mazzucchelli, Eastman), titan nguyên chất và beta, thép không gỉ, Monel, TR90, Ultem, sợi carbon, sừng trâu và gỗ. Tất cả đều từ nhà cung cấp được chứng nhận và tuân thủ tiêu chuẩn an toàn quốc tế (FDA, CE, RoHS, Dự luật 65 của California).' },
    { question: 'Sản phẩm có những chứng nhận nào?', answer: 'Kính của chúng tôi đáp ứng các tiêu chuẩn quốc tế gồm FDA (Hoa Kỳ), CE (EU), RoHS và Dự luật 65 của California. Chúng tôi kiểm soát chất lượng nghiêm ngặt xuyên suốt quá trình sản xuất. Tài liệu chứng nhận được cung cấp theo yêu cầu để phục vụ hồ sơ tuân thủ của bạn.' },
    { question: 'Các bạn có tùy chỉnh bao bì và nhận diện thương hiệu không?', answer: 'Có, chúng tôi cung cấp giải pháp thương hiệu toàn diện: khắc hoặc in logo lên gọng, đuôi càng kính tùy chỉnh, hộp đựng mang thương hiệu, khăn lau, hộp giấy và thẻ treo. Toàn bộ vật liệu bao bì có thể đồng bộ với bảng màu và ngôn ngữ thiết kế của thương hiệu bạn.' },
    { question: 'Các bạn chấp nhận điều khoản thanh toán nào?', answer: 'Điều khoản tiêu chuẩn là đặt cọc 30% để bắt đầu sản xuất và thanh toán 70% còn lại trước khi giao hàng. Chúng tôi chấp nhận T/T (chuyển khoản ngân hàng) và thư tín dụng (L/C) cho đơn hàng lớn. Điều khoản thanh toán có thể được thỏa thuận với đối tác đã hợp tác ổn định.' },
    { question: 'Các bạn giao hàng đến đâu?', answer: 'Chúng tôi giao hàng toàn cầu. Các thị trường chính gồm Hoa Kỳ, Liên minh châu Âu, Vương quốc Anh, Nhật Bản, Hàn Quốc, Úc, Trung Đông và Đông Nam Á. Chúng tôi hợp tác với đối tác vận tải đáng tin cậy cho cả đường hàng không và đường biển.' },
    { question: 'Làm thế nào để yêu cầu báo giá?', answer: 'Truy cập trang báo giá (/vi/quote/) và điền yêu cầu vào biểu mẫu. Vui lòng nêu loại gọng, vật liệu mong muốn, số lượng dự kiến và yêu cầu thiết kế cụ thể. Đội ngũ kinh doanh thường phản hồi trong vòng 24 giờ.' },
    { question: 'Các bạn có thể làm theo thiết kế gọng hiện có không?', answer: 'Có, chúng tôi có thể tái tạo hoặc điều chỉnh thiết kế gọng hiện có. Chỉ cần cung cấp hình ảnh tham khảo, bản vẽ kỹ thuật hoặc mẫu thực tế; đội ngũ kỹ thuật sẽ lập thông số sẵn sàng cho sản xuất. Chúng tôi bảo đảm mọi thiết kế đều tôn trọng quyền sở hữu trí tuệ.' },
    { question: 'Quy trình kiểm soát chất lượng như thế nào?', answer: 'Mỗi gọng đều qua nhiều bước kiểm tra: vật liệu đầu vào, chất lượng trong quá trình sản xuất, kiểm tra cuối cùng (kiểm tra 100% ngoại quan, độ vừa vặn, độ hoàn thiện và độ chính xác kích thước) và lấy mẫu ngẫu nhiên trước khi giao hàng. Chúng tôi lưu báo cáo chi tiết cho từng lô sản xuất.' },
  ],
  ms: [
    { question: 'Berapakah kuantiti pesanan minimum (MOQ) anda?', answer: 'MOQ standard kami ialah 300 unit bagi setiap model dan warna. Untuk reka bentuk tersuai, MOQ mungkin berbeza mengikut bahan dan kerumitan. Hubungi pasukan jualan kami untuk keperluan khusus; kami menawarkan kelonggaran kepada rakan niaga jangka panjang.' },
    { question: 'Adakah anda menawarkan perkhidmatan OEM dan ODM?', answer: 'Ya! Kssmi mengkhusus dalam OEM (pembuatan mengikut reka bentuk pelanggan) dan ODM (reka bentuk dan pembuatan asal). OEM: kami menghasilkan cermin mata tepat mengikut spesifikasi dan reka bentuk anda. ODM: pasukan reka bentuk dalaman kami membangunkan koleksi eksklusif untuk jenama anda berdasarkan pasaran sasaran dan pilihan anda. Kedua-duanya merangkumi penyesuaian penuh bahan, warna, logo dan pembungkusan.' },
    { question: 'Berapa lamakah tempoh pengeluaran anda?', answer: 'Tempoh pengeluaran standard ialah 25-35 hari selepas pengesahan sampel. Pesanan segera boleh diterima bergantung pada kapasiti pengeluaran semasa. Pembangunan sampel biasanya mengambil masa 7-10 hari. Tempoh penghantaran pesanan pukal berbeza mengikut destinasi dan kaedah: udara 5-7 hari, laut 25-35 hari.' },
    { question: 'Bolehkah saya memesan sampel sebelum pengeluaran pukal?', answer: 'Sudah tentu. Kami menyediakan pembangunan sampel supaya anda dapat menilai kualiti, kesesuaian pemakaian dan kemasan sebelum mengesahkan pengeluaran pukal. Bayaran sampel biasanya ditolak daripada nilai pesanan pukal anda. Kami boleh menghasilkan sampel mengikut spesifikasi anda, termasuk warna, bahan dan penjenamaan tersuai.' },
    { question: 'Apakah bahan yang digunakan untuk cermin mata anda?', answer: 'Kami menggunakan pelbagai bahan: asetat berkualiti tinggi (Mazzucchelli, Eastman), titanium tulen dan beta, keluli tahan karat, Monel, TR90, Ultem, gentian karbon, tanduk kerbau dan kayu. Semua bahan diperoleh daripada pembekal bertauliah dan mematuhi piawaian keselamatan antarabangsa (FDA, CE, RoHS, Proposisi 65 California).' },
    { question: 'Apakah pensijilan produk anda?', answer: 'Cermin mata kami memenuhi piawaian antarabangsa termasuk FDA (AS), CE (EU), RoHS dan Proposisi 65 California. Kami melaksanakan kawalan kualiti yang ketat sepanjang pengeluaran. Dokumen pensijilan tersedia atas permintaan untuk rekod pematuhan anda.' },
    { question: 'Adakah anda menyediakan pembungkusan dan penjenamaan tersuai?', answer: 'Ya, kami menawarkan penyelesaian penjenamaan lengkap: ukiran atau cetakan logo pada bingkai, hujung tangkai tersuai, bekas berjenama, kain pembersih, kotak dan tag gantung. Semua bahan pembungkusan boleh diselaraskan dengan palet warna dan gaya reka bentuk jenama anda.' },
    { question: 'Apakah syarat pembayaran yang anda terima?', answer: 'Syarat standard kami ialah deposit 30% untuk memulakan pengeluaran dan baki 70% sebelum penghantaran. Kami menerima T/T (pindahan bank) dan Surat Kredit (L/C) untuk pesanan yang lebih besar. Syarat pembayaran boleh dibincangkan bagi perkongsian yang telah terjalin.' },
    { question: 'Ke manakah anda membuat penghantaran?', answer: 'Kami menghantar ke seluruh dunia. Pasaran utama termasuk Amerika Syarikat, Kesatuan Eropah, United Kingdom, Jepun, Korea Selatan, Australia, Timur Tengah dan Asia Tenggara. Kami bekerjasama dengan rakan pengangkutan yang boleh dipercayai untuk penghantaran udara dan laut.' },
    { question: 'Bagaimanakah saya meminta sebut harga?', answer: 'Lawati halaman Sebut Harga kami (/ms/quote/) dan lengkapkan borang dengan keperluan anda. Sertakan jenis bingkai, bahan pilihan, anggaran kuantiti dan sebarang permintaan reka bentuk khusus. Pasukan jualan kami biasanya membalas dalam masa 24 jam.' },
    { question: 'Bolehkah anda menghasilkan reka bentuk bingkai sedia ada?', answer: 'Ya, kami boleh menghasilkan semula atau menyesuaikan reka bentuk bingkai sedia ada. Berikan imej rujukan, lukisan teknikal atau sampel fizikal, dan pasukan kejuruteraan kami akan menyediakan spesifikasi untuk pengeluaran. Kami memastikan semua reka bentuk menghormati hak harta intelek.' },
    { question: 'Apakah proses kawalan kualiti anda?', answer: 'Setiap bingkai melalui pemeriksaan berperingkat: pemeriksaan bahan masuk, kawalan kualiti semasa pengeluaran, pemeriksaan akhir (pemeriksaan 100% terhadap rupa, kesesuaian pemakaian, kemasan dan ketepatan dimensi) serta pensampelan rawak sebelum penghantaran. Kami menyimpan laporan terperinci bagi setiap kelompok pengeluaran.' },
  ],
  jv: [
    { question: 'Pira jumlah pesenan minimal (MOQ) sampeyan?', answer: 'MOQ standar kita yaiku 300 unit saben model saben warna. Kanggo desain khusus, MOQ bisa beda gumantung bahan lan kerumitan. Hubungi tim dodolan kanggo kabutuhan tartamtu; kita fleksibel kanggo mitra jangka panjang.' },
    { question: 'Apa sampeyan nyedhiyakake layanan OEM lan ODM?', answer: 'Ya! Kssmi duwe spesialisasi ing OEM (produksi miturut desain pelanggan) lan ODM (desain asli lan produksi). OEM: kita nggawe kacamata persis miturut spesifikasi lan desain sampeyan. ODM: tim desain internal kita nggawe koleksi eksklusif kanggo merek sampeyan adhedhasar pasar sasaran lan pilihan sampeyan. Loro layanan iki kalebu pangaturan bahan, warna, logo, lan kemasan kanthi lengkap.' },
    { question: 'Suwene wektu produksi sampeyan?', answer: 'Wektu produksi standar yaiku 25-35 dina sawise sampel disetujoni. Pesenan mendesak bisa ditampa gumantung kapasitas produksi saiki. Pangembangan sampel biasane mbutuhake 7-10 dina. Wektu pangiriman pesenan gedhe beda miturut tujuan lan cara: liwat udara 5-7 dina, liwat segara 25-35 dina.' },
    { question: 'Apa aku bisa pesen sampel sadurunge produksi massal?', answer: 'Mesthi bisa. Kita nyedhiyakake pangembangan sampel supaya sampeyan bisa mriksa kualitas, kepenakan nalika dienggo, lan asil pungkasan sadurunge nyetujoni produksi massal. Biaya sampel biasane dikurangi saka regane pesenan gedhe sampeyan. Kita bisa nggawe sampel miturut spesifikasi sampeyan, kalebu warna, bahan, lan tandha merek khusus.' },
    { question: 'Bahan apa wae sing digunakake kanggo kacamata sampeyan?', answer: 'Kita nggunakake maneka bahan: asetat kualitas dhuwur (Mazzucchelli, Eastman), titanium murni lan beta, baja tahan karat, Monel, TR90, Ultem, serat karbon, sungu kebo, lan kayu. Kabeh bahan asale saka pemasok sing disertifikasi lan nyukupi standar keamanan internasional (FDA, CE, RoHS, Proposisi 65 California).' },
    { question: 'Sertifikasi apa wae sing diduweni produk sampeyan?', answer: 'Kacamata kita nyukupi standar internasional kalebu FDA (AS), CE (Uni Eropa), RoHS, lan Proposisi 65 California. Kita nindakake kontrol kualitas sing ketat sajrone produksi. Dokumen sertifikasi bisa diwenehake yen dijaluk kanggo cathetan kepatuhan sampeyan.' },
    { question: 'Apa sampeyan nyedhiyakake kemasan lan tandha merek khusus?', answer: 'Ya, kita nawakake solusi merek lengkap: ukiran utawa cetakan logo ing bingkai, pucuk gagang khusus, wadhah kacamata kanthi merek, kain pembersih, kothak, lan label gantung. Kabeh bahan kemasan bisa dicocogake karo palet warna lan gaya desain merek sampeyan.' },
    { question: 'Syarat pembayaran apa sing sampeyan tampa?', answer: 'Syarat standar kita yaiku dhuwit muka 30% kanggo miwiti produksi lan sisa 70% sadurunge pangiriman. Kita nampa T/T (transfer bank) lan Letter of Credit (L/C) kanggo pesenan sing luwih gedhe. Syarat pembayaran bisa dirembug kanggo kemitraan sing wis lumaku.' },
    { question: 'Sampeyan ngirim menyang ngendi wae?', answer: 'Kita ngirim menyang saindenging donya. Pasar utama kalebu Amerika Serikat, Uni Eropa, Inggris, Jepang, Korea Kidul, Australia, Timur Tengah, lan Asia Tenggara. Kita kerja bareng mitra angkutan sing dipercaya kanggo pangiriman liwat udara lan segara.' },
    { question: 'Kepiye carane njaluk penawaran rega?', answer: 'Bukak kaca Penawaran Rega (/jv/quote/) lan isi formulir nganggo kabutuhan sampeyan. Tulisen jinis bingkai, bahan sing dikarepake, kira-kira jumlah, lan panjaluk desain khusus. Tim dodolan kita biasane mangsuli sajrone 24 jam.' },
    { question: 'Apa sampeyan bisa nggawe desain bingkai sing wis ana?', answer: 'Ya, kita bisa nggawe maneh utawa nyetel desain bingkai sing wis ana. Wenehana gambar referensi, gambar teknis, utawa sampel fisik, lan tim teknik kita bakal nggawe spesifikasi sing siap diprodhuksi. Kita mesthekake kabeh desain ngajeni hak kekayaan intelektual.' },
    { question: 'Kepiye proses kontrol kualitas sampeyan?', answer: 'Saben bingkai ngalami pamriksan pirang-pirang tahap: bahan sing mlebu, kontrol kualitas sajrone produksi, pamriksan pungkasan (pamriksan 100% kanggo tampilan, kesesuaian nalika dienggo, asil pungkasan, lan akurasi ukuran), sarta sampel acak sadurunge pangiriman. Kita nyimpen laporan kualitas rinci kanggo saben batch produksi.' },
  ],
  tg: [
    { question: 'Ҳадди ақали миқдори фармоиш (MOQ) чанд аст?', answer: 'MOQ-и стандартии мо барои ҳар модел дар ҳар ранг 300 дона аст. Барои тарҳҳои фармоишӣ он вобаста ба мавод ва мураккабӣ метавонад фарқ кунад. Барои талаботи мушаххас бо гурӯҳи фурӯш тамос гиред; мо барои шарикони дарозмуддат шароити чандир пешниҳод мекунем.' },
    { question: 'Оё шумо хизматрасониҳои OEM ва ODM пешниҳод мекунед?', answer: 'Бале! Kssmi ба OEM (истеҳсол аз рӯйи тарҳи муштарӣ) ва ODM (тарҳрезӣ ва истеҳсоли аслӣ) тахассус дорад. OEM: мо айнакҳоро дақиқан мувофиқи мушаххасот ва тарҳҳои шумо месозем. ODM: гурӯҳи дохилии тарроҳии мо барои бренди шумо бо назардошти бозори мақсаднок ва хоҳишҳоятон маҷмӯаҳои истисноӣ таҳия мекунад. Ҳар ду хизматрасонӣ мутобиқсозии пурраи мавод, ранг, тамға ва бастабандиро дар бар мегиранд.' },
    { question: 'Муҳлати истеҳсол чанд аст?', answer: 'Муҳлати стандартии истеҳсол пас аз тасдиқи намуна 25-35 рӯз аст. Фармоишҳои таъҷилӣ вобаста ба иқтидори ҷории истеҳсолӣ қабул мешаванд. Таҳияи намуна одатан 7-10 рӯз мегирад. Муҳлати интиқоли фармоиши яклухт аз макон ва усул вобаста аст: ҳавоӣ 5-7 рӯз, баҳрӣ 25-35 рӯз.' },
    { question: 'Оё пеш аз истеҳсоли яклухт намуна фармоиш додан мумкин аст?', answer: 'Албатта. Мо намуна таҳия мекунем, то шумо пеш аз тасдиқи истеҳсоли яклухт сифат, мувофиқати пӯшидан ва пардозро арзёбӣ кунед. Арзиши намуна одатан аз маблағи фармоиши яклухт тарҳ мешавад. Намунаҳоро мувофиқи мушаххасоти шумо, аз ҷумла ранг, мавод ва нишонаҳои брендии фармоишӣ месозем.' },
    { question: 'Барои айнакҳо кадом маводро истифода мебаред?', answer: 'Мо маводи гуногунро истифода мебарем: ацетати баландсифат (Mazzucchelli, Eastman), титани холис ва бета-титан, пӯлоди зангногир, Монел, TR90, Ultem, нахи карбон, шохи говмеш ва чӯб. Ҳамаи мавод аз таъминкунандагони сертификатдор гирифта шуда, ба стандартҳои байналмилалии бехатарӣ (FDA, CE, RoHS, Пешниҳоди 65-и Калифорния) мувофиқанд.' },
    { question: 'Маҳсулоти шумо кадом сертификатҳоро доранд?', answer: 'Айнакҳои мо ба стандартҳои байналмилалӣ, аз ҷумла FDA (ИМА), CE (ИА), RoHS ва Пешниҳоди 65-и Калифорния мувофиқанд. Мо дар тамоми раванди истеҳсол назорати қатъии сифатро нигоҳ медорем. Ҳуҷҷатҳои сертификатсия бо дархост барои сабтҳои мутобиқати шумо пешниҳод мешаванд.' },
    { question: 'Оё бастабандӣ ва тамғагузории фармоишӣ пешниҳод мекунед?', answer: 'Бале, мо ҳалли пурраи брендиро пешниҳод мекунем: ҳаккокӣ ё чопи тамға дар чорчӯбаҳо, нӯгҳои фармоишии дастаҳо, ғилофҳои брендӣ, матоъҳои тозакунӣ, қуттиҳо ва барчаспҳои овезон. Ҳамаи маводи бастабандиро ба рангҳо ва услуби тарроҳии бренди шумо мутобиқ мекунем.' },
    { question: 'Кадом шартҳои пардохтро қабул мекунед?', answer: 'Шартҳои стандартӣ: 30% пешпардохт барои оғози истеҳсол ва 70% бақия пеш аз ирсол. Мо T/T (интиқоли бонкӣ) ва барои фармоишҳои калон аккредитив (L/C) қабул мекунем. Барои шарикони доимӣ шартҳои пардохтро метавон муҳокима кард.' },
    { question: 'Ба куҷо интиқол медиҳед?', answer: 'Мо ба тамоми ҷаҳон интиқол медиҳем. Бозорҳои асосӣ Иёлоти Муттаҳида, Иттиҳоди Аврупо, Британияи Кабир, Ҷопон, Кореяи Ҷанубӣ, Австралия, Ховари Миёна ва Осиёи Ҷанубу Шарқӣ мебошанд. Барои интиқоли ҳавоӣ ва баҳрӣ бо шарикони боэътимод кор мекунем.' },
    { question: 'Чӣ гуна пешниҳоди нархро дархост кунам?', answer: 'Ба саҳифаи пешниҳоди нарх (/tg/quote/) гузаред ва варақаро бо талаботи худ пур кунед. Навъи чорчӯба, маводи дилхоҳ, миқдори тахминӣ ва дархостҳои мушаххаси тарҳро нишон диҳед. Гурӯҳи фурӯш одатан дар давоми 24 соат ҷавоб медиҳад.' },
    { question: 'Оё метавонед тарҳи мавҷудаи чорчӯбаро такрор кунед?', answer: 'Бале, мо тарҳҳои мавҷудаи чорчӯбаро такрор ё мутобиқ карда метавонем. Тасвирҳои намунавӣ, нақшаҳои техникӣ ё намунаҳои ҷисмониро пешниҳод кунед ва гурӯҳи муҳандисии мо мушаххасоти омода барои истеҳсолро таҳия мекунад. Мо риояи ҳуқуқи моликияти зеҳниро дар ҳамаи тарҳҳо таъмин мекунем.' },
    { question: 'Раванди назорати сифати шумо чӣ гуна аст?', answer: 'Ҳар чорчӯба аз санҷиши чандмарҳилагӣ мегузарад: санҷиши маводи воридотӣ, назорати сифат ҳангоми истеҳсол, санҷиши ниҳоӣ (санҷиши 100% намуди зоҳирӣ, мувофиқати пӯшидан, пардоз ва дақиқии андозаҳо) ва санҷиши намунаҳои тасодуфӣ пеш аз ирсол. Барои ҳар силсилаи истеҳсолӣ ҳисоботи муфассали сифатро нигоҳ медорем.' },
  ],
};
